-- FRIEND_CODE of a player.
create or replace function public.friend_code_state(p_player uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'code',          'NEXA-' || p.tag,
    'bonus_cents',   greatest(0, public.config_bigint('social', '{friendCode,bonusCents}', 500000)),
    'redeemed',      p.friend_code_at is not null,
    'redeemed_from', (select jsonb_build_object('nickname', i.nickname, 'tag', i.tag)
                        from public.profiles i where i.id = p.friend_code_from),
    'redeemed_at',   p.friend_code_at,
    'invited',       (select count(*) from public.profiles x where x.friend_code_from = p.id))
    from public.profiles p where p.id = p_player;
$$;

create or replace function public.get_friend_code()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid;
begin
  v_player := public.require_player();
  return public.friend_code_state(v_player);
end;
$$;
comment on function public.get_friend_code() is 'RPC: the own friend code, whether one was redeemed, how many friends came (ADR-111).';

create or replace function public.redeem_friend_code(p_request_id uuid, p_code text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player  uuid;
  v_replay  jsonb;
  v_tag     text;
  v_owner   public.profiles;
  v_me      public.profiles;
  v_bonus   bigint;
  v_paid    bigint;
  v_cash    bigint;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'redeem_friend_code');
  if v_replay is not null then
    return v_replay;
  end if;
  -- "NEXA-K7Q2", "nexa k7q2", "#K7Q2" and "K7Q2" all mean the same code
  v_tag := regexp_replace(upper(coalesce(p_code, '')), '[^A-Z0-9]', '', 'g');
  if length(v_tag) = 8 and left(v_tag, 4) = 'NEXA' then
    v_tag := right(v_tag, 4);
  end if;
  if v_tag !~ '^[A-HJ-NP-Z2-9]{4}$' then
    perform public.api_error('friend_code_unknown');
  end if;
  perform public.lock_player_accounts(v_player);
  select * into v_me from public.profiles where id = v_player for update;
  if v_me.friend_code_at is not null then
    perform public.api_error('friend_code_used');
  end if;
  select * into v_owner from public.profiles p where p.tag = v_tag and not p.is_deactivated;
  if v_owner.id is null then
    perform public.api_error('friend_code_unknown');
  end if;
  if v_owner.id = v_player then
    perform public.api_error('friend_code_self');
  end if;

  v_bonus := greatest(0, public.config_bigint('social', '{friendCode,bonusCents}', 500000));
  update public.profiles set friend_code_from = v_owner.id, friend_code_at = now() where id = v_player;
  v_paid := public.state_pay_partial(v_player, v_bonus, 'mission_reward', 'Freundescode von ' || v_owner.nickname,
                                     'friend_code:' || v_player::text);
  perform public.loan_withhold(v_player, v_paid, 'friend_code:' || v_player::text);
  perform public.social_notify(v_owner.id, 'friend_code_redeemed', 'Freundescode eingelöst',
    v_me.nickname || ' ist mit deinem Code dabei.',
    jsonb_build_object('nickname', v_me.nickname, 'tag', v_me.tag), '/friends', 'friend_code:' || v_player::text);

  select a.balance_cents into v_cash from public.ledger_accounts a
   where a.owner_player_id = v_player and a.kind = 'player_cash';
  return public.request_complete(v_player, p_request_id,
    public.friend_code_state(v_player) || jsonb_build_object('paid_cents', v_paid, 'cash_after_cents', v_cash));
end;
$$;
comment on function public.redeem_friend_code(uuid, text) is 'RPC: redeem a friend''s code once for the bonus (ADR-111).';

do $$
declare
  f text;
begin
  foreach f in array array['public.friend_code_state(uuid)'] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array['public.get_friend_code()', 'public.redeem_friend_code(uuid, text)'] loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated, service_role', f);
  end loop;
end;
$$;

-- ===== supabase/updates/20261203000100_currency_choice.sql =====
-- ===== idempotent copy of migrations/20261203000100_currency_choice.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 0100 · Euro is the default currency again; dollar and NX are a display choice (ADR-113)
-- =============================================================================
-- ADR-110 renamed the currency to NX everywhere. The owner decided otherwise: the game shows euros by default, and
-- every player may pick dollar or NX as the sign behind amounts. That choice lives in the client (a display
-- setting); the server writes one neutral form, the euro sign, and the client swaps it for the chosen sign.
-- So this migration takes the server texts back: the money text helpers and the crypto event texts say "€", and
-- amounts stored as "... NX" become "... €" again. The stablecoin keeps its neutral name "Eins-Stabil".
-- Idempotent: runs unchanged as supabase/updates/20261203000100_currency_choice.sql.

-- German short money text for news: "420,0 Mio. €", "1,96 Mrd. €", "400 Tsd. €".
create or replace function public.format_eur_short(p_cents bigint)
returns text
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_abs  numeric := abs(coalesce(p_cents, 0));
  v_sign text := case when coalesce(p_cents, 0) < 0 then '-' else '' end;
begin
  if v_abs >= 100000000000 then
    return v_sign || replace(to_char(v_abs / 100000000000, 'FM999990.00'), '.', ',') || ' Mrd. €';
  elsif v_abs >= 100000000 then
    return v_sign || replace(to_char(v_abs / 100000000, 'FM999990.0'), '.', ',') || ' Mio. €';
  elsif v_abs >= 100000 then
    return v_sign || to_char(round(v_abs / 100000), 'FM999990') || ' Tsd. €';
  end if;
  return v_sign || to_char(round(v_abs / 100), 'FM999990') || ' €';
end;
$$;

-- German money text for system messages: "1.234 €", "-56 €".
create or replace function public.format_eur(p_cents bigint)
returns text
language sql
immutable
set search_path = ''
as $$
  select case when p_cents < 0 then '-' else '' end
      || reverse(regexp_replace(reverse(round(abs(p_cents) / 100.0)::bigint::text), '(\d{3})(?=\d)', '\1.', 'g'))
      || ' €';
$$;

-- "{target}" in titles and descriptions: euros for money metrics ("2.000 €"), else the number.
create or replace function public.mission_text(p_text text, p_metric text, p_target bigint)
returns text
language sql
immutable
set search_path = ''
as $$
  select replace(p_text, '{target}',
           case when public.mission_is_money_metric(p_metric)
                then replace(to_char(p_target / 100, 'FM999G999G999G990'), ',', '.') || ' €'
                else p_target::text end);
$$;

-- Crypto event texts (as in M5a).
create or replace function public.crypto_event_text(p_key text, p_name text)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select case p_key
    when 'hack' then jsonb_build_object('title', 'Hack bei ' || n, 'body', 'Angreifer haben Geld aus dem Pool gestohlen. Der Kurs bricht ein.')
    when 'bug' then jsonb_build_object('title', 'Bug bei ' || n, 'body', 'Ein Fehler im Smart Contract verunsichert die Halter.')
    when 'influencer' then jsonb_build_object('title', 'Influencer feiert ' || n, 'body', 'Ein bekannter Influencer schwärmt von der Währung. Der Kurs springt.')
    when 'exchange_listing' then jsonb_build_object('title', n || ' an einer Börse gelistet', 'body', 'Eine große Krypto-Börse nimmt die Währung auf.')
    when 'delisting_rumor' then jsonb_build_object('title', 'Delisting-Gerücht um ' || n, 'body', 'Es heißt, eine Börse wolle die Währung streichen.')
    when 'whale_buy' then jsonb_build_object('title', 'Wal kauft ' || n, 'body', 'Ein Großanleger kauft in großem Stil.')
    when 'whale_dump' then jsonb_build_object('title', 'Wal verkauft ' || n, 'body', 'Ein Großanleger wirft seine Coins auf den Markt.')
    when 'partnership' then jsonb_build_object('title', 'Partnerschaft für ' || n, 'body', 'Ein Unternehmen will die Währung nutzen.')
    when 'fud' then jsonb_build_object('title', 'Angstmache um ' || n, 'body', 'Gerüchte und Panik drücken den Kurs.')
    when 'network_upgrade' then jsonb_build_object('title', 'Netzwerk-Upgrade bei ' || n, 'body', 'Das Netzwerk wird schneller und günstiger.')
    when 'depeg' then jsonb_build_object('title', n || ' verliert die Bindung', 'body', 'Der Stablecoin ist nicht mehr 1 € wert.')
    when 'meme_wave' then jsonb_build_object('title', 'Meme-Welle', 'body', 'Shitcoins sind plötzlich überall gefragt.')
    when 'regulation' then jsonb_build_object('title', 'Regulierung trifft ' || n, 'body', 'Neue Regeln für Kryptowährungen drücken den ganzen Markt.')
    when 'rug_pull' then jsonb_build_object('title', 'Rug Pull bei ' || n, 'body', 'Die Macher haben in großem Stil Coins verkauft. Der Kurs stürzt ab.')
    when 'exposed' then jsonb_build_object('title', 'Werbedeal von ' || n || ' aufgeflogen', 'body', 'Die bezahlte Influencer-Werbung ist aufgeflogen: Der Hype ist weg, der Kurs fällt.')
    when 'dead' then jsonb_build_object('title', n || ' ist tot', 'body', 'Der Kurs ist fast null. In einem Tag wird die Währung gestrichen.')
    when 'delisted' then jsonb_build_object('title', n || ' gestrichen', 'body', 'Die Währung ist vom Markt verschwunden.')
    when 'closed' then jsonb_build_object('title', n || ' eingestellt', 'body', 'Der Pool wurde nach Coins an alle Halter ausgezahlt.')
    else jsonb_build_object('title', 'Neuigkeit zu ' || n, 'body', 'Bei der Währung hat sich etwas getan.')
  end
  from (select coalesce(p_name, 'einer Kryptowährung') as n) x;
$$;

-- Amounts written as "5.000 NX", "1,2 Mio. NX" or "1 NX" while ADR-110 was in force: back to the euro sign. Only a
-- number (or Tsd./Mio./Mrd.) followed by NX as a whole word is touched. The ledger and the profiles were never
-- rewritten and stay as they are.
do $$
declare
  r record;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public' and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying') and c.is_generated = 'NEVER'
       and c.table_name not like 'ledger%' and c.table_name not in ('profiles', 'game_config')
     order by c.table_name, c.column_name
  loop
    begin
      execute format(
        'update public.%I set %I = regexp_replace(%I, %L, %L, %L) where %I ~ %L',
        r.table_name, r.column_name, r.column_name,
        '([0-9]|Tsd\.|Mio\.|Mrd\.) NX\M', '\1 €', 'g',
        r.column_name, '([0-9]|Tsd\.|Mio\.|Mrd\.) NX\M');
    exception when others then
      -- a table that guards its rows keeps its wording
      null;
    end;
  end loop;
end;
$$;

-- ===== supabase/updates/20261203000150_open_signup.sql =====
-- ===== idempotent copy of migrations/20261203000150_open_signup.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 0150 · Sign-up without an invite code (ADR-114, replaces ADR-010)
-- =============================================================================
-- The owner opened the game: registering no longer needs an invite code. handle_new_user() is the M4d version with
-- one change: auth.inviteRequired defaults to false. An operator can still close the doors again by setting
-- game_config.auth = {"inviteRequired": true}; then the old rule applies (a valid, unused code or NX005).
-- A code that is sent anyway and valid is still counted; an unknown one is ignored while codes are optional.
-- The 18+ confirmation stays mandatory. The tables invite_codes and invite_code_redemptions stay.
-- Idempotent: runs unchanged as supabase/updates/20261203000150_open_signup.sql.

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_meta            jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  v_code            text  := nullif(upper(btrim(coalesce(v_meta ->> 'invite_code', ''))), '');
  v_invite_required boolean := public.config_boolean('auth', '{inviteRequired}', false);
  v_age_required    boolean := public.config_boolean('auth', '{ageConfirmationRequired}', true);
  v_age_confirmed   boolean := lower(coalesce(v_meta ->> 'age_confirmed', 'false')) in ('true', '1', 'yes');
  v_start_cents     bigint  := greatest(public.config_bigint('economy', '{startingCapitalCents}', 1000000), 0);
  v_vault_hours     double precision := greatest(0, least(
                        public.config_double('economy', '{vaultInitialHours}', 2),
                        public.config_double('economy', '{vaultCapHours}', 8)));
  v_max_len         integer := public.config_double('names', '{maxLength}', 20)::integer;
  v_invite          public.invite_codes;
  v_base            text;
  v_nickname        text;
  v_reason          text;
  v_attempt         integer := 0;
begin
  -- 18+ confirmation ---------------------------------------------------------
  if v_age_required and not v_age_confirmed then
    raise exception 'age confirmation (18+) is required' using errcode = 'NX007';
  end if;

  -- invite code ---------------------------------------------------------------
  if v_code is not null then
    select i.* into v_invite from public.invite_codes i where i.code = v_code for update;
    if not found
       or not v_invite.is_active
       or (v_invite.expires_at is not null and v_invite.expires_at <= now())
       or v_invite.used_count >= v_invite.max_uses then
      if v_invite_required then
        raise exception 'invite code is invalid, expired or used up' using errcode = 'NX005';
      end if;
      v_code := null;
    end if;
  elsif v_invite_required then
    raise exception 'an invite code is required' using errcode = 'NX005';
  end if;

  -- nickname: cleaned as before, forbidden names are rejected (the client
  -- pre-checks with check_nickname), taken names and lookalikes of taken names
  -- (same name key, ADR-085) get a numeric suffix; the tag comes from the column default
  v_base := left(regexp_replace(coalesce(v_meta ->> 'nickname', ''), '[^A-Za-z0-9_]', '', 'g'), v_max_len);
  if length(v_base) < 3 then
    v_base := 'Trader';
    v_nickname := v_base || (floor(random() * 90000) + 10000)::integer::text;
  else
    v_reason := public.name_violation(v_base, 'player');
    if v_reason in ('name_profanity', 'name_reserved') then
      perform public.api_error(v_reason);
    end if;
    v_nickname := v_base;
  end if;
  while exists (select 1 from public.profiles p
                 where lower(p.nickname) = lower(v_nickname) or public.name_key(p.nickname) = public.name_key(v_nickname)) loop
    v_attempt := v_attempt + 1;
    if v_attempt > 20 then
      raise exception 'could not generate a unique nickname' using errcode = 'NX007';
    end if;
    v_nickname := left(v_base, 15) || (floor(random() * 90000) + 10000)::integer::text;
  end loop;

  -- player rows ----------------------------------------------------------------
  insert into public.profiles (id, nickname) values (new.id, v_nickname);
  insert into public.player_private (player_id, age_confirmed_at)
  values (new.id, case when v_age_confirmed then now() end);
  insert into public.player_settings (player_id) values (new.id);
  insert into public.vaults (player_id, accrual_started_at)
  values (new.id, public.game_now() - make_interval(secs => v_vault_hours * 3600));
  insert into public.login_streaks (player_id) values (new.id);

  insert into public.player_unlocks (player_id, unlock_key)
  select new.id, u.key from public.unlocks u where u.level <= 1;

  insert into public.notification_preferences (player_id, type_key, in_app_enabled, push_enabled)
  select new.id, t.key, t.default_in_app, t.default_push from public.notification_types t;

  -- ledger: cash + reserve account, starting capital from the state -----------
  insert into public.ledger_accounts (kind, owner_player_id, label) values ('player_cash', new.id, 'Cash');
  insert into public.ledger_accounts (kind, owner_player_id, label)
  values ('player_reserve', new.id, 'Reserved (orders, subscriptions, margin)');

  if v_start_cents > 0 then
    perform public.state_payout(new.id, v_start_cents, 0, 'starting_capital', 'Starting capital',
                                'profile', new.id, 'starting_capital:' || new.id::text);
  end if;

  -- consume the invite ---------------------------------------------------------
  if v_code is not null then
    update public.invite_codes set used_count = used_count + 1 where code = v_code;
    insert into public.invite_code_redemptions (code, player_id) values (v_code, new.id);
  end if;

  return new;
end;
$$;
comment on function public.handle_new_user() is
  'Trigger on auth.users: checks the 18+ confirmation (and an invite code only while auth.inviteRequired is set), creates profile, settings, vault and ledger accounts.';

commit;
